<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\Booking;use App\Models\Service;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class BookingApiController extends Controller{public function index(Request $r){return response()->json($r->user()->customerBookings()->with(['service','provider','payment'])->latest()->paginate(15));}public function store(Request $r){$d=$r->validate(['service_id'=>'required|exists:services,id','booking_date'=>'required|date|after_or_equal:today','booking_time'=>'required|date_format:H:i','address'=>'required|string|min:5','customer_note'=>'nullable|string']);$s=Service::where('is_active',true)->findOrFail($d['service_id']);$b=Booking::create(['customer_id'=>$r->user()->id,'provider_id'=>$s->provider_id,'service_id'=>$s->id,'booking_date'=>$d['booking_date'],'booking_time'=>$d['booking_time'],'address'=>$d['address'],'amount'=>$s->price,'customer_note'=>$d['customer_note']??null]);return response()->json($b->load('service'),201);}public function show(Request $r,Booking $booking){abort_unless($booking->customer_id===$r->user()->id||$booking->provider_id===$r->user()->id||$r->user()->isAdmin(),403);return response()->json($booking->load(['service','customer','provider','payment','review']));}}
